    const result = new TransitionMatrix();
    for (let i = 0; i <= 3; i++) {
      for (let j = 0; j <= 3; j++) {
        let x = 0n;
        for (let k = 0; k <= 3; k++) {
          x = (x + (this.get(i, k) * other.get(k, j))) % modulo;
        }
        result.set(i, j, x);
      }
    }
    return result;
  }
}

function identity_matrix() {
  const result = new TransitionMatrix();
  result.set(0, 0, 1n);
  result.set(1, 1, 1n);
  result.set(2, 2, 1n);
  result.set(3, 3, 1n);
  return result;
}

function ant_matrix() {
  const result = new TransitionMatrix();
  for (let i = 0; i <= 3; i++) {
    for (let j = 0; j <= 3; j++) {
      result.set(i, j, 1n);
    }
  }
  result.set(0, 0, 0n);
  result.set(1, 1, 0n);
  result.set(2, 2, 0n);
  result.set(3, 3, 0n);
  return result;
}

